import fs from 'node:fs/promises';import path from 'node:path';import {createHmac,createHash} from 'node:crypto';import {chromium} from 'playwright';
const env=process.argv.includes('--dev')?'DEV':'PROD';
const root=path.join(process.env.LOCALAPPDATA,'FVI-QA-Private-20260925'),stamp=new Date().toISOString().replace(/[:.]/g,'-'),lane='carson-home-team-access-20261003-'+env;
const privateOut=path.join(root,lane,stamp),out=path.resolve('scripts/qa/output',lane,stamp);await fs.mkdir(privateOut,{recursive:true});await fs.mkdir(out,{recursive:true});
const load=async n=>JSON.parse(await fs.readFile(path.join(root,n),'utf8'));
const transport=await load(env==='PROD'?'FVI-QA-TRANSPORT-PROD-20261001.json':'FVI-QA-TRANSPORT-DEV-20261002.json'),seeds=await load('FVI-QA-FULL-PRODUCTION-ACTOR-SEEDS-20261001.json'),nonadmin=await load('FVI-QA-NONADMIN-ACTOR-SEEDS-20261001.json');
if(transport.projectRef!==(env==='PROD'?'YOUR_PROJECT_REF':'YOUR_PROJECT_REF')||new URL(transport.apiUrl).protocol!=='https:'||String(transport.anonKey).startsWith('sb_secret_'))throw Error('Transport isolation failure');
let tenant=env==='PROD'?seeds.tenant_id:null;const host=env==='PROD'?'https://app.reconiq.example':'https://dev.app.reconiq.example',summary={at:new Date().toISOString(),parentAck:env==='PROD'?'5fbb724d':'4d170bfd',environment:env,host,tenant,readOnlyBusinessOperations:true,privateEvidence:privateOut,actors:[]};
function totp(secret){let bits='';for(const char of secret.toUpperCase().replaceAll('=',''))bits+='ABCDEFGHIJKLMNOPQRSTUVWXYZ234567'.indexOf(char).toString(2).padStart(5,'0');const bytes=[];for(let i=0;i+8<=bits.length;i+=8)bytes.push(parseInt(bits.slice(i,i+8),2));const counter=Buffer.alloc(8);counter.writeBigUInt64BE(BigInt(Math.floor(Date.now()/30000)));const d=createHmac('sha1',Buffer.from(bytes)).update(counter).digest(),offset=d[d.length-1]&15;return String((d.readUInt32BE(offset)&0x7fffffff)%1000000).padStart(6,'0');}
async function auth(endpoint,data,token){const r=await fetch(transport.apiUrl+'/auth/v1/'+endpoint,{method:'POST',headers:{apikey:transport.anonKey,'Content-Type':'application/json',...(token?{Authorization:'Bearer '+token}:{})},body:JSON.stringify(data),signal:AbortSignal.timeout(25000)});const j=await r.json();if(!r.ok)throw Error('Auth '+endpoint.split('?')[0]+' HTTP '+r.status+' '+(j.code??j.error_code??'refused'));return j;}
const browser=await chromium.launch({headless:true});
try{
const authHtml=await fetch(host+'/auth',{signal:AbortSignal.timeout(25000)}),html=await authHtml.text();summary.deployment={authHttp:authHtml.status,styles:[]};for(const asset of [...new Set(html.match(/\/assets\/styles-[A-Za-z0-9_-]+\.css/g)??[])]){const r=await fetch(host+asset),b=Buffer.from(await r.arrayBuffer());summary.deployment.styles.push({asset,http:r.status,sha256:createHash('sha256').update(b).digest('hex')});}
for(const label of (env==='PROD'?['kepler-org-admin','kepler-scoped-observer','nonadmin-analyst']:['DEV-maker','DEV-checker'])){
let seed,mfa;if(env==='PROD'){seed=[...seeds.actors,...nonadmin.actors].find(a=>a.label===label);mfa=await load('FVI-QA-MFA-'+label+'-20261001.json');}else{const text=await fs.readFile(path.join(root,'FVI-QA-Access-'+label+'-20260925.cred'),'utf8');const field=n=>text.split(/\r?\n/).find(l=>l.startsWith('- '+n+': ')||l.startsWith(n+': '))?.split(': ').slice(1).join(': ').trim().replace(/^`|`$/g,'');seed={label,email:field('Account'),password:field('Temporary password')};if(!seed.email||!seed.password)throw Error('Protected DEV credential format incomplete');}const record={label,id:seed.user_id,stages:[],pages:[],reads:{}};summary.actors.push(record);let context;
try{
if(mfa&&(mfa.user_id!==seed.user_id||mfa.tenant_id!==tenant||mfa.project_ref!==transport.projectRef))throw Error('MFA identity mismatch');
const signed=await auth('token?grant_type=password',{email:seed.email,password:seed.password});let session=signed;if(mfa){const challenge=await auth('factors/'+mfa.factor_id+'/challenge',{},signed.access_token);session=await auth('factors/'+mfa.factor_id+'/verify',{challenge_id:challenge.id,code:totp(mfa.totp_secret)},signed.access_token);}else{seed.user_id=session.user.id;record.id=seed.user_id;record.verifiedMfaFactors=(session.user.factors??[]).filter(f=>f.status==='verified').length;}const claims=JSON.parse(Buffer.from(session.access_token.split('.')[1],'base64url'));await fs.writeFile(path.join(privateOut,label+'-session.json'),JSON.stringify(session));
if(claims.sub!==seed.user_id||(env==='PROD'&&claims.aal!=='aal2'))throw Error('Fresh actual AAL2 mismatch');record.aal=claims.aal;record.expires=claims.exp;
const headers={apikey:transport.anonKey,Authorization:'Bearer '+session.access_token};
async function read(name,params,opts={}){const url=transport.apiUrl+'/rest/v1/'+name+(params?'?'+new URLSearchParams(params):'');const r=await fetch(url,{headers:{...headers,...(opts.count?{Prefer:'count=exact'}:{})},...(opts.rpc?{method:'POST',body:JSON.stringify(opts.rpc),headers:{...headers,'Content-Type':'application/json'}}:{}),signal:AbortSignal.timeout(25000)});const text=await r.text();let data;try{data=JSON.parse(text);}catch{data=null;}record.reads[opts.key??name]={http:r.status,count:r.headers.get('content-range'),rows:Array.isArray(data)?data.length:null,error:r.ok?null:data?.code??'read_refused'};await fs.writeFile(path.join(privateOut,label+'-'+(opts.key??name).replaceAll('/','_')+'.json'),JSON.stringify({http:r.status,data}));return {http:r.status,data};}
if(env==='DEV'){const tr=await read('tenants',{select:'id,slug',slug:'eq.reconiq-assurance-lab-development'});tenant=tr.data?.[0]?.id;summary.tenant=tenant;if(!tenant)throw Error('DEV QA tenant unavailable');}
const role=await read('tenant_members',{select:'tenant_id,user_id,role,active',tenant_id:'eq.'+tenant,user_id:'eq.'+seed.user_id});record.membership=role.data;
const tenants=await read('tenants',{select:'id,slug',id:'eq.'+tenant});const slug=tenants.data?.[0]?.slug;if(!slug)throw Error('Caller cannot resolve authorized QA tenant slug');record.slug=slug;
const scope=await read('rpc/get_workspace_dashboard_team_scope',null,{rpc:{_tenant_id:tenant},key:'team-scope'});record.teamScope=scope.data;
const date=new Date(),since=new Date(Date.UTC(date.getUTCFullYear(),date.getUTCMonth(),date.getUTCDate()-29)).toISOString();record.windowSince=since;
await read('recon_definitions',{select:'id',tenant_id:'eq.'+tenant,created_by:'eq.'+seed.user_id,limit:'0'},{count:true,key:'my-reconciliations'});
await read('recon_runs',{select:'id',tenant_id:'eq.'+tenant,run_by:'eq.'+seed.user_id,started_at:'gte.'+since,limit:'0'},{count:true,key:'my-runs'});
await read('workspace_data_sources',{select:'id',tenant_id:'eq.'+tenant,created_by:'eq.'+seed.user_id,limit:'0'},{count:true,key:'my-data-sources'});
await read('business_units',{select:'id,name,tenant_id',tenant_id:'eq.'+tenant});const groups=await read('tenant_groups',{select:'id,name,tenant_id,bu_id,is_system',tenant_id:'eq.'+tenant});await read('bu_group_assignments',{select:'bu_id,group_id,role',tenant_id:'eq.'+tenant});if(groups.data?.length)await read('tenant_group_members',{select:'group_id,user_id',group_id:'in.('+groups.data.map(g=>g.id).join(',')+')',user_id:'eq.'+seed.user_id});await read('reference_data_tables',{select:'id,name,tenant_id,row_count,is_active',tenant_id:'eq.'+tenant});
context=await browser.newContext({viewport:{width:1440,height:1050}});await context.addInitScript(({key,session})=>localStorage.setItem(key,JSON.stringify(session)),{key:'sb-'+transport.projectRef+'-auth-token',session});const page=await context.newPage();page.setDefaultTimeout(8000);const pending=[],events=[];let responseId=0;
page.on('response',r=>{const u=new URL(r.url());if(u.origin===host&&/server|api/.test(u.pathname)){events.push({path:u.pathname,status:r.status()});if(!/auth/.test(u.pathname)){const id=++responseId;pending.push(r.text().then(body=>fs.writeFile(path.join(privateOut,label+'-response-'+id+'.txt'),body)).catch(()=>{}));}}});
async function capture(name,url,waitLabel){await page.goto(url,{waitUntil:'domcontentloaded',timeout:35000});if(waitLabel)await page.getByRole('button',{name:waitLabel,exact:true}).waitFor({timeout:20000});else await page.waitForTimeout(1800);const closer=page.locator('.driver-popover-close-btn');if(await closer.isVisible().catch(()=>false)){await closer.click();await page.waitForTimeout(250);}await fs.writeFile(path.join(privateOut,label+'-storage.json'),JSON.stringify(await context.storageState()));const text=await page.locator('body').innerText();await fs.writeFile(path.join(privateOut,label+'-'+name+'-text.txt'),text);await page.screenshot({path:path.join(out,label+'-'+name+'.png'),fullPage:true});const buttons=await page.getByRole('button').evaluateAll(es=>es.map(e=>({text:e.innerText,label:e.getAttribute('aria-label'),disabled:e.disabled,pressed:e.getAttribute('aria-pressed'),title:e.title})));record.pages.push({name,url:page.url(),buttons,alerts:await page.getByRole('alert').allTextContents(),textFile:path.join(privateOut,label+'-'+name+'-text.txt')});}
await capture('my',host+'/'+slug+'/workspace?page=dashboard','My scope');
const team=page.getByRole('button',{name:'Team scope',exact:true});record.teamButtonDisabled=await team.isDisabled();if(!record.teamButtonDisabled){await team.click();await page.getByText('Team workspace intelligence',{exact:false}).waitFor({timeout:20000});await page.waitForTimeout(2000);await fs.writeFile(path.join(privateOut,label+'-team-text.txt'),await page.locator('body').innerText());await page.screenshot({path:path.join(out,label+'-team.png'),fullPage:true});record.pages.push({name:'team',url:page.url(),alerts:await page.getByRole('alert').allTextContents()});}
record.tenantButtonDisabled=await page.getByRole('button',{name:'Tenant scope',exact:true}).isDisabled();
await capture('business-units',host+'/'+slug+'/tenant?page=business-units');await capture('groups',host+'/'+slug+'/tenant?page=groups');await capture('reference',host+'/'+slug+'/workspace?page=reference');
record.network=events;await Promise.allSettled(pending);await fs.writeFile(path.join(privateOut,label+'-storage.json'),JSON.stringify(await context.storageState()));record.status='captured';
}catch(e){record.status='blocked';record.error=String(e.message).split('\n')[0].replace(/Bearer\s+\S+/g,'Bearer [redacted]');console.log(JSON.stringify({label,status:record.status,error:record.error}));}finally{await context?.close();}
await fs.writeFile(path.join(out,'summary.json'),JSON.stringify(summary,null,2));console.log(JSON.stringify({label,status:record.status,aal:record.aal,role:record.membership,teamScope:record.teamScope,reads:record.reads,teamButtonDisabled:record.teamButtonDisabled,tenantButtonDisabled:record.tenantButtonDisabled}));
}
}finally{await browser.close();await fs.writeFile(path.join(out,'summary.json'),JSON.stringify(summary,null,2));console.log('RESULT='+path.join(out,'summary.json'));}
